var i=`0816-dikgobe`;var n=`world-0816`;var s=`BW`;var a=`southern-africa`;var r=4;var o=649;var l={en:`Dikgobe`,ua:`Дікгобе`};var g={en:`Dikgobe is a Botswana dish made with black-eyed peas, sorghum, sweet corn. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Дікгобе, страва кухні країни Ботсвана. Основні складники: квасоля чорноочка, сорго, солодка кукурудза. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Soak dried legumes in plenty of cool water for 480 minutes, then drain and discard the soaking water. Cook them fully in fresh water.`,ua:`Замочіть сухі бобові у великій кількості прохолодної води на 480 хвилин, потім злийте та вилийте воду від замочування. Повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:480,i:[[`black-eyed-peas`,230,`g`],[`water`,800,`ml`]]},{en:`Boil the soaked cowpeas in fresh water until completely tender; discard soaking water.`,ua:`Варіть замочений коров’ячий горох у свіжій воді до повної м’якості; воду від замочування злийте.`,t:[`boiling`],m:75,i:[[`water`,1100,`ml`]]},{en:`Cook sorghum separately until tender before combining it with the beans and sweet corn.`,ua:`Зваріть сорго окремо до м’якості перед змішуванням із бобовими та кукурудзою.`,t:[`boiling`],m:75,i:[[`sorghum`,170,`g`],[`water`,700,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 16 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 16 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:16,i:[[`sweet-corn`,280,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,32,`g`]]}];var u={slug:i,id:n,country:`BW`,region:a,servings:4,minutes:649,title:l,text:g,steps:d};export{s as country,u as default,n as id,o as minutes,a as region,r as servings,i as slug,d as steps,g as text,l as title};